// Maps the Font Awesome 6 icon names used by <Card icon="..."> in the
// Mintlify content to the Iconify id astro-icon needs (`<set>:<name>`).
//
// Generated by checking each of the 80 distinct icon names used across the
// corpus against the `fa6-solid` and `fa6-brands` Iconify sets (see
// site/README.md). Three names (`package`, `rectangle-vertical-history`,
// `shield-check`) don't exist as free Font Awesome icons in either set —
// Mintlify's own icon picker draws from a larger (partly Pro) catalog. Those
// three fall back to the closest free equivalent; this is a decorative,
// build-time substitution, not a content change.
export const ICON_MAP: Record<string, string> = {
  apple: 'fa6-brands:apple',
  git: 'fa6-brands:git',
  node: 'fa6-brands:node',

  // No exact free-icon match; closest visual equivalent.
  package: 'fa6-solid:box',
  'rectangle-vertical-history': 'fa6-solid:clock-rotate-left',
  'shield-check': 'fa6-solid:shield',

  'arrow-down': 'fa6-solid:arrow-down',
  'arrow-left': 'fa6-solid:arrow-left',
  'arrow-right': 'fa6-solid:arrow-right',
  bed: 'fa6-solid:bed',
  bell: 'fa6-solid:bell',
  blender: 'fa6-solid:blender',
  book: 'fa6-solid:book',
  'boxes-stacked': 'fa6-solid:boxes-stacked',
  broom: 'fa6-solid:broom',
  building: 'fa6-solid:building',
  calendar: 'fa6-solid:calendar',
  'calendar-days': 'fa6-solid:calendar-days',
  'calendar-plus': 'fa6-solid:calendar-plus',
  'chart-bar': 'fa6-solid:chart-bar',
  'chart-line': 'fa6-solid:chart-line',
  'chart-simple': 'fa6-solid:chart-simple',
  check: 'fa6-solid:check',
  'chevron-right': 'fa6-solid:chevron-right',
  'circle-dot': 'fa6-solid:circle-dot',
  'circle-info': 'fa6-solid:circle-info',
  clock: 'fa6-solid:clock',
  cloud: 'fa6-solid:cloud',
  code: 'fa6-solid:code',
  compass: 'fa6-solid:compass',
  cube: 'fa6-solid:cube',
  database: 'fa6-solid:database',
  desktop: 'fa6-solid:desktop',
  'diagram-project': 'fa6-solid:diagram-project',
  'door-open': 'fa6-solid:door-open',
  ellipsis: 'fa6-solid:ellipsis',
  envelope: 'fa6-solid:envelope',
  filter: 'fa6-solid:filter',
  flag: 'fa6-solid:flag',
  gear: 'fa6-solid:gear',
  gears: 'fa6-solid:gears',
  globe: 'fa6-solid:globe',
  headset: 'fa6-solid:headset',
  house: 'fa6-solid:house',
  'id-card': 'fa6-solid:id-card',
  image: 'fa6-solid:image',
  images: 'fa6-solid:images',
  inbox: 'fa6-solid:inbox',
  key: 'fa6-solid:key',
  keyboard: 'fa6-solid:keyboard',
  language: 'fa6-solid:language',
  'layer-group': 'fa6-solid:layer-group',
  link: 'fa6-solid:link',
  list: 'fa6-solid:list',
  lock: 'fa6-solid:lock',
  'magnifying-glass': 'fa6-solid:magnifying-glass',
  map: 'fa6-solid:map',
  'map-pin': 'fa6-solid:map-pin',
  message: 'fa6-solid:message',
  mobile: 'fa6-solid:mobile',
  palette: 'fa6-solid:palette',
  paperclip: 'fa6-solid:paperclip',
  plug: 'fa6-solid:plug',
  'right-to-bracket': 'fa6-solid:right-to-bracket',
  rocket: 'fa6-solid:rocket',
  route: 'fa6-solid:route',
  'scale-balanced': 'fa6-solid:scale-balanced',
  server: 'fa6-solid:server',
  shield: 'fa6-solid:shield',
  sitemap: 'fa6-solid:sitemap',
  'square-check': 'fa6-solid:square-check',
  star: 'fa6-solid:star',
  sun: 'fa6-solid:sun',
  tag: 'fa6-solid:tag',
  train: 'fa6-solid:train',
  'triangle-exclamation': 'fa6-solid:triangle-exclamation',
  user: 'fa6-solid:user',
  wrench: 'fa6-solid:wrench',
  xmark: 'fa6-solid:xmark',
};

/** Resolve a Mintlify Card `icon` value to an Iconify id, if known. */
export function resolveIcon(name: string | undefined): string | undefined {
  if (!name) return undefined;
  return ICON_MAP[name];
}
